package com.pabonaki.model;import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.index.Indexed;import org.springframework.data.mongodb.core.mapping.Document;import java.time.Instant;@Document("products")public class Product{@Id private String id;@Indexed(unique=true)private String sku;private String name;private String slug;private String description;private String category;private double price;private double discountPercent=0;private int stock;private String imageUrl;private String status="ACTIVE";private Instant createdAt=Instant.now();private Instant updatedAt=Instant.now();public String getId(){return id;}public void setId(String v){id=v;}public String getSku(){return sku;}public void setSku(String v){sku=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getSlug(){return slug;}public void setSlug(String v){slug=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public String getCategory(){return category;}public void setCategory(String v){category=v;}public double getPrice(){return price;}public void setPrice(double v){price=v;}public double getDiscountPercent(){return discountPercent;}public void setDiscountPercent(double v){discountPercent=Math.max(0,Math.min(90,v));}public double getFinalPrice(){return Math.round(price*(1-discountPercent/100.0)*100.0)/100.0;}public int getStock(){return stock;}public void setStock(int v){stock=v;}public String getImageUrl(){return imageUrl;}public void setImageUrl(String v){imageUrl=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}public void setUpdatedAt(Instant v){updatedAt=v;}}